nodes.command:
set -e
docker image inspect lab3/node-exporter:20261017 --format '{{.Id}}'
test -d /root/mysql/data && test -d /root/mysql/conf.d && test -d /root/mysql/sql && test -d /root/mysql/log
CID=$(docker ps -q --filter name=lab_mysql | head -1)
docker exec -i "$CID" sh -c 'MYSQL_PWD="$MYSQL_ROOT_PASSWORD" mysql -uroot -N' <<'SQL'
SELECT VERSION();
SELECT 'original_products',COUNT(*) FROM oomall_demo.goods_product;
SELECT 'experiment_products',COUNT(*),MAX(id) FROM oomall_lab3_teacher.goods_product;
SELECT 'experiment_goods',COUNT(*) FROM oomall_lab3_teacher.goods_goods;
SELECT 'experiment_onsale',COUNT(*) FROM oomall_lab3_teacher.goods_onsale;
SELECT 'next_id',AUTO_INCREMENT FROM information_schema.TABLES WHERE TABLE_SCHEMA='oomall_lab3_teacher' AND TABLE_NAME='goods_product';
SELECT GRANTEE,TABLE_SCHEMA,PRIVILEGE_TYPE FROM information_schema.SCHEMA_PRIVILEGES WHERE GRANTEE LIKE '%demouser%' ORDER BY GRANTEE,TABLE_SCHEMA,PRIVILEGE_TYPE;
SQL
